using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections;
using System.Collections.Generic;
using System.Web.Script.Serialization;
internal static class TougliReader {
 internal const string Site="https://tougli.barbofus.com";internal const string Api="https://api.tougli.barbofus.com";internal const int MaxBytes=8*1024*1024;
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=MaxBytes,RecursionLimit=64};
 internal static bool ValidSlug(string s){return s!=null&&s.Length<=120&&Regex.IsMatch(s,@"^[a-z0-9]+(?:-[a-z0-9]+)*$");}
 internal static Dictionary<string,object> Obj(object o){return o as Dictionary<string,object>??new Dictionary<string,object>();}
 internal static object Get(object o,string key){object v;return Obj(o).TryGetValue(key,out v)?v:null;}
 internal static object[] Arr(object o){var a=o as object[];if(a!=null)return a;var list=o as ArrayList;return list==null?new object[0]:list.ToArray();}
 internal static string S(object o){return o==null?"":Convert.ToString(o,System.Globalization.CultureInfo.InvariantCulture);}
 internal static string Plain(object o){string s=S(o);if(s.Length>100000)throw new InvalidDataException("Un texte du guide est trop long.");s=Regex.Replace(s,@"<(script|style)\b[^>]*>.*?</\1>","",RegexOptions.IgnoreCase|RegexOptions.Singleline);s=Regex.Replace(s,@"<br\s*/?>|</(?:p|div|li|h[1-6])>","\n",RegexOptions.IgnoreCase);return WebUtility.HtmlDecode(Regex.Replace(s,"<[^>]*>","")).Trim();}
 internal static string Fr(object o){return o is string?Plain(o):Plain(Get(o,"fr")??Get(o,"en"));}
 internal static string Name(object o){return Fr(Get(o,"name"));}
 internal static string SafeUrl(object o){Uri u;string s=S(o);return Uri.TryCreate(s,UriKind.Absolute,out u)&&u.Scheme=="https"&&String.IsNullOrEmpty(u.UserInfo)?u.AbsoluteUri:"";}
 static object Root(string json){if(Encoding.UTF8.GetByteCount(json)>MaxBytes)throw new InvalidDataException("Guide trop volumineux.");var root=Json.DeserializeObject(json);var data=Get(root,"data");if(data==null)throw new InvalidDataException("Réponse Tougli non reconnue.");return data;}
 internal static List<TougliGuideInfo> Catalogue(string json){var data=Root(json);if(Get(data,"guides")==null)throw new InvalidDataException("Catalogue Tougli non reconnu.");var guides=Arr(Get(data,"guides"));if(guides.Length>2000)throw new InvalidDataException("Catalogue trop volumineux.");return guides.Where(g=>!Object.Equals(Get(g,"isDraft"),true)&&ValidSlug(S(Get(g,"url")))).Select(g=>new TougliGuideInfo{Slug=S(Get(g,"url")),Title=Plain(Get(g,"title")),Category=Fr(Get(g,"category")),Level=Number(Get(g,"optimalLevel"))}).Where(g=>g.Title!="").GroupBy(g=>g.Slug).Select(g=>g.First()).ToList();}
 static int Number(object o){int n;return Int32.TryParse(S(o),out n)?n:0;}
 static string Summary(object o,int depth=0){if(o==null||depth>7)return "";if(o is string)return Plain(o);var a=Arr(o);if(a.Length>0)return String.Join(" · ",a.Take(200).Select(v=>Summary(v,depth+1)).Where(v=>v!=""));var obj=Obj(o);if(obj.Count==0)return "";if(obj.ContainsKey("fr"))return Fr(o);var counted=Get(o,"monster")??Get(o,"item");if(counted!=null&&Get(o,"count")!=null)return S(Get(o,"count"))+" × "+Name(counted);string name=Name(o);if(name!="")return name;return String.Join("\n",obj.Where(k=>new[]{"text","detail","note","combat","monster","payload","job","dungeons","achievements","quests"}.Contains(k.Key)).Select(k=>Summary(k.Value,depth+1)).Where(v=>v!=""));}
 static string Label(string type){switch(type){case "combat":return "Combat";case "bashMobs":return "Monstres";case "dungeon":return "Donjon";case "dungeonChoice":return "Donjon au choix";case "needPlayer":return "Joueurs nécessaires";case "job":return "Métier";case "hours":return "Horaire";case "spell":return "Sort";case "achievement":return "Succès";case "songe":return "Songes";case "note":return "Note";case "url":return "Lien";default:return "À consulter sur Tougli ("+type+")";}}
 static bool? Condition(string value,DofusCharacter c){var pair=(value??"").Split('=');if(pair.Length!=2)return null;string actual=pair[0]=="Classe"?c.classCode:pair[0]=="Ali"?c.alignment:pair[0]=="Ordre"?c.order:null;if(String.IsNullOrEmpty(actual))return null;return actual==pair[1];}
 internal static TougliDocument Parse(string json,DofusCharacter character){var data=Root(json);var guide=Get(data,"guide");string slug=S(Get(guide,"url"));if(!ValidSlug(slug)||Get(guide,"objectives")==null||Plain(Get(guide,"title"))=="")throw new InvalidDataException("Le format du guide Tougli n’est pas reconnu.");var doc=new TougliDocument{Slug=slug,Title=Plain(Get(guide,"title")),Description=Plain(Get(guide,"description")),Hash=WorkspaceNext.Hash(Encoding.UTF8.GetBytes(json))};string section="";int total=0;
  Action<object[],string,int> walk=null;walk=delegate(object[] objectives,string prefix,int depth){if(depth>12)throw new InvalidDataException("Structure du guide trop profonde.");for(int i=0;i<objectives.Length;i++){if(++total>10000)throw new InvalidDataException("Trop d’étapes dans ce guide.");var o=objectives[i];string type=S(Get(o,"type"));var payload=Get(o,"payload");string id=prefix+"/"+(Get(o,"id")==null?"index:"+i:S(Get(o,"id")));
    if(type=="title"){section=Fr(payload);continue;}if(type=="group"){walk(Arr(payload),id,depth+1);continue;}if(type=="choice"){var branches=Arr(payload);var selected=branches.FirstOrDefault(b=>Condition(S(Get(b,"condition")),character)==true);if(selected!=null){walk(Arr(Get(selected,"objectives")),id,depth+1);continue;}doc.Steps.Add(new TougliStep{Key="choice/"+id,Title="Choix du personnage à renseigner",Section=section,Details="Branches : "+String.Join(" · ",branches.Select(b=>S(Get(b,"condition"))))+"\nVérifiez la classe, l’alignement et l’ordre du personnage. Ce choix n’a pas été deviné.",Url=Site+"/guide/"+slug,CanComplete=false});continue;}
    var step=new TougliStep{Section=section,Url=Site+"/guide/"+slug};string payloadId=S(payload);if(type=="quest"){var q=Get(Get(data,"quests"),payloadId);if(q==null){step.Title="Quête "+payloadId;step.Details="Détails absents : consultez Tougli.";step.CanComplete=false;}else{step.QuestId=payloadId;step.Title=Name(q);var lines=new List<string>();foreach(var pre in Arr(Get(q,"prerequisites"))){string preType=S(Get(pre,"type")),preId=S(Get(pre,"id"));var reference=Get(Get(data,preType=="quest"?"quests":preType=="achievement"?"achievements":""),preId);string detail=Name(reference);if(detail=="")detail=Summary(pre);if(detail=="")detail=preType+" "+preId;lines.Add("Prérequis · "+detail);}foreach(var task in Arr(Get(q,"objectives"))){string t=S(Get(task,"type"));var p=Get(task,"payload");string text=Summary(p);if(t=="url")text=Plain(Get(p,"text"))+" · "+SafeUrl(Get(p,"url"));lines.Add(Label(t)+" · "+(text==""?"Détails sur le guide source":text));}foreach(var item in Arr(Get(q,"items"))){var resource=Get(item,"item");int count=Number(Get(item,"count"));string name=Name(resource);if(name!=""&&count>0)step.Resources.Add(new TougliResource{Id=S(Get(resource,"id")),Name=name,Count=count});}step.Details=String.Join("\n",lines);var link=SafeUrl(Get(q,"dplnUrl"));if(link!="")step.Url=link;}}
    else if(type=="achievement"){var achievement=Get(Get(data,"achievements"),payloadId);step.Title="Succès · "+(Name(achievement)==""?payloadId:Name(achievement));step.Details=Summary(achievement);}
    else if(type=="take_quests"){var qs=Arr(Get(payload,"quests")).Select(q=>Name(Get(Get(data,"quests"),S(q)))).ToArray();string text=Fr(Get(payload,"text"));for(int j=qs.Length;j>=1;j--)text=text.Replace("&"+j,qs[j-1]);step.Title="Quêtes à prendre / avancer";step.Details=text==""?String.Join("\n",qs):text;}
    else if(type=="note"){step.Title="À savoir";step.Details=Fr(payload);}
    else{step.Title="Étape à consulter sur Tougli";step.Details="Ce format (« "+type+" ») n’est pas encore affiché par Mon espace.";step.CanComplete=false;}
    step.Details=step.Details??"";if(step.Details.Length>60000)throw new InvalidDataException("Étape trop volumineuse.");string identity=type+"/"+payloadId+"/"+step.Title+"/"+step.Details;step.Key=id+"/"+WorkspaceNext.Hash(Encoding.UTF8.GetBytes(identity)).Substring(0,20);var coords=Regex.Match(step.Details,@"\[\s*(-?\d{1,3})\s*,\s*(-?\d{1,3})\s*\]");step.Coordinates=coords.Success?coords.Groups[1].Value+","+coords.Groups[2].Value:"";doc.Steps.Add(step);
  }};walk(Arr(Get(guide,"objectives")),"g",0);if(doc.Steps.Count==0)throw new InvalidDataException("Ce guide ne contient pas d’étapes affichables.");return doc;
 }
 internal static string CachePath(Store store,string slug){if(!ValidSlug(slug))throw new InvalidDataException("Adresse de guide invalide.");return Path.Combine(store.Root,"TougliCache",slug+".json");}
 internal static string Cached(Store store,string slug){string file=CachePath(store,slug);if(!File.Exists(file))return null;if(new FileInfo(file).Length>MaxBytes)throw new InvalidDataException("Cache de guide trop volumineux.");return File.ReadAllText(file);}
 internal static void Cache(Store store,string slug,string json){string file=CachePath(store,slug);Directory.CreateDirectory(Path.GetDirectoryName(file));string temp=file+".tmp";try{File.WriteAllText(temp,json,new UTF8Encoding(false));if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
